B.HX=s(["Karar ge\xe7ersiz olur.","Karar \u015fekl\xee/maddi anlamda kesinle\u015fir ve icra edilebilir h\xe2le gelir.","Dava yeniden ilk derece mahkemesinde g\xf6r\xfcl\xfcr.","Karar resen Yarg\u0131tay\u2019a g\xf6nderilir."],t.s)
B.O9=new A.aG("kanun_06",B.c8,"S\xfcresinde kanun yoluna ba\u015fvurulmayan bir karar bak\u0131m\u0131ndan sonu\xe7 nedir?",B.HX,1,"Kanun yolu s\xfcresi i\xe7inde ba\u015fvurulmazsa veya kanun yolu kapal\u0131ysa karar kesinle\u015fir; kesinle\u015fen karar icra edilebilir ve kesin h\xfck\xfcm (res judicata) etkisi do\u011furur.")
