B.I0=s(["Davac\u0131n\u0131n davas\u0131ndan vazge\xe7mesidir.","Daval\u0131n\u0131n, davac\u0131n\u0131n talep sonucuna k\u0131smen veya tamamen muvafakat etmesidir.","Taraflar\u0131n uzla\u015fmas\u0131d\u0131r.","Mahkemenin davay\u0131 kabul etmesidir."],t.s)
B.NY=new A.aG("taraf_02",B.c7,"Kabul nedir?",B.I0,1,"HMK m. 308: Kabul, davac\u0131n\u0131n talep sonucuna daval\u0131n\u0131n k\u0131smen veya tamamen muvafakat etmesidir.")
